import type { BadgeVariants } from '~/components/ui/badge';
import type { CanvassingInteractionImportStatus } from '~/client';

interface ImportStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const importStatusConfig: Record<CanvassingInteractionImportStatus, ImportStatusEntry> = {
  PENDING: { label: 'Pending', variant: 'info' },
  PROCESSING: { label: 'Processing', variant: 'info' },
  SUCCESS: { label: 'Success', variant: 'success' },
  FAILED: { label: 'Failed', variant: 'destructive' },
};

// CanvassingInteractionImportStatus keys are UPPERCASE, so snakeCaseToCapitalizedCase doesn't fit — fall back to the raw value.
export function getImportStatus(status: CanvassingInteractionImportStatus): ImportStatusEntry {
  return importStatusConfig[status] ?? { label: status, variant: 'default' };
}
